const charRows=[['mary','Mary Lennox','A neglected, imperious nine-year-old whose curiosity, outdoor work, and new friendships awaken sympathy and purpose.',1,'#7d7353'],['colin','Colin Craven','Mary’s hidden cousin, convinced he is dying until companionship and the garden challenge the story built around his illness.',2,'#687b63'],['dickon','Dickon Sowerby','Martha’s younger brother, at ease with plants and animals and generous with the practical knowledge the garden needs.',3,'#667a58'],['martha','Martha Sowerby','A candid young housemaid whose stories of home, moor, and Dickon offer Mary her first model of ordinary affection.',4,'#8b6d55'],['archibald','Archibald Craven','Mary’s widowed uncle, physically burdened and emotionally exiled by grief after his wife’s death.',5,'#665f70'],['susan','Susan Sowerby','Martha and Dickon’s mother, whose grounded care reaches both the manor children and the absent master.',6,'#8a7560'],['ben','Ben Weatherstaff','An elderly gardener whose gruff reserve conceals loyalty to Lilias Craven and affection for the robin and children.',7,'#6f7052'],['medlock','Mrs Medlock','The manor housekeeper, protective of its rules and Colin’s secrecy but capable of recognizing real improvement.',8,'#786456'],['dr-craven','Dr Craven','Colin’s physician and cousin, caught between medical caution, family expectation, and surprise at the boy’s recovery.',9,'#65727a'],['lilias','Lilias Craven','Archibald’s late wife and Colin’s mother, remembered through the garden and the love that once animated the house.',10,'#8c7480'],['mrs-lennox','Mrs Lennox','Mary’s beautiful, socially absorbed mother, emotionally distant before the epidemic ends the Indian household.',11,'#96736e'],['ayah','Mary’s Ayah','The servant who raised and obeyed Mary in India before becoming one of the epidemic’s first victims.',12,'#79695c']]
